// PyLearn service worker. Generated by build.py - do not edit.
// The drills app (small) is precached on install so it works offline right away.
// Pyodide (about 14 MB, only needed for coding lessons) is cached the first time a
// coding lesson loads it, in its own cache that survives app updates.
const VERSION = "6fa8410634a4";
const CORE = "pylearn-core-" + VERSION;
const PYO = "pylearn-pyodide-314.0.8";
const CORE_ASSETS = [
 "./",
 "ai_tutor.js",
 "app.js",
 "careful.js",
 "code.html",
 "data/drills.json",
 "data/lessons.json",
 "data/meta.json",
 "data/runner.py",
 "data/runtime.json",
 "drills.css",
 "drills.js",
 "game.js",
 "icons/apple-touch-icon.png",
 "icons/icon-192.png",
 "icons/icon-512.png",
 "icons/icon-maskable-512.png",
 "icons/icon.svg",
 "index.html",
 "manifest.json",
 "style.css",
 "sync.js",
 "tutor.js",
 "worker.js"
];
const PYODIDE_ASSETS = [
 "pyodide/pyodide.mjs",
 "pyodide/pyodide.js",
 "pyodide/pyodide.asm.mjs",
 "pyodide/pyodide.asm.wasm",
 "pyodide/python_stdlib.zip",
 "pyodide/pyodide-lock.json"
];
const abs = (u) => new URL(u, self.registration.scope).href;
const PYO_SET = new Set(PYODIDE_ASSETS.map(abs));

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CORE);
    await cache.addAll(CORE_ASSETS.map((u) => new Request(u, { cache: "reload" })));
    // Carry Pyodide over from an older install (any cache) so coding stays offline-ready.
    const pyo = await caches.open(PYO);
    for (const url of PYO_SET) {
      if (await pyo.match(url)) continue;
      const old = await caches.match(url);
      if (old) await pyo.put(url, old);
    }
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys())
      if (key.startsWith("pylearn-") && key !== CORE && key !== PYO) await caches.delete(key);
    await self.clients.claim();
  })());
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  const url = new URL(req.url);
  if (req.method !== "GET" || url.origin !== self.location.origin) return;
  const clean = url.origin + url.pathname;
  if (PYO_SET.has(clean)) {
    event.respondWith((async () => {
      const pyo = await caches.open(PYO);
      const hit = await pyo.match(clean);
      if (hit) return hit;
      const res = await fetch(req);
      if (res.ok) await pyo.put(clean, res.clone());
      return res;
    })());
    return;
  }
  event.respondWith((async () => {
    const cache = await caches.open(CORE);
    let hit = await cache.match(req, { ignoreSearch: true });
    if (!hit && req.mode === "navigate")
      hit = await cache.match(url.pathname.endsWith("code.html") ? "./code.html" : "./index.html");
    if (hit) return hit;
    return fetch(req);
  })());
});
